// ─────────────────────────────────────────────────────────────
// Supabase getAll returns ONE item PER ROW.
// Use $items() to collect ALL rows from multi-row nodes.
// ─────────────────────────────────────────────────────────────

const session = $node["Fetch Session1"]?.json || {};
const resume  = $node["Fetch Resume"]?.json    || {};
const jd      = $node["Fetch JD"]?.json        || {};

const questionRows   = ($items("Fetch Questions1") || []).map(i => i.json);
const answerRows     = ($items("Fetch Answers1")   || []).map(i => i.json);
const proctoringRows = ($items("Fetch Proctoring1") || []).map(i => i.json);

// Build question lookup
const questionMap = {};
questionRows.forEach(q => { questionMap[q.id] = q; });

// Build answer list for the LLM
const answerList = answerRows.map(a => ({
  question: questionMap[a.question_id]?.question_text || 'Unknown',
  answer:   a.answer_text || 'No answer provided',
  type:     questionMap[a.question_id]?.question_type || 'technical'
}));

// ─── Build structured proctoring summary ───────────────────
const criticalEvents = proctoringRows.filter(e => e.severity === 'critical');
const warningEvents  = proctoringRows.filter(e => e.severity === 'warning');

const countByType = {};
proctoringRows.forEach(e => {
  countByType[e.event_type] = (countByType[e.event_type] || 0) + 1;
});

// Risk level based on critical event count
let proctoringRisk = 'low';
if (criticalEvents.length >= 5 || proctoringRows.length >= 20) proctoringRisk = 'high';
else if (criticalEvents.length >= 2 || warningEvents.length >= 5) proctoringRisk = 'medium';

const notableEvents = [
  ...criticalEvents,
  ...warningEvents
].slice(0, 10).map(e => ({
  type:      e.event_type,
  severity:  e.severity,
  timestamp: e.timestamp
}));

const proctoringSummary = {
  total_events:    proctoringRows.length,
  critical_count:  criticalEvents.length,
  warning_count:   warningEvents.length,
  risk_level:      proctoringRisk,
  by_type:         countByType,
  notable_events:  notableEvents
};

const truncate = (t, max) => !t ? '' : t.length > max ? t.slice(0, max) + '...[truncated]' : t;

const prompt = `You are a senior technical recruiter writing a post-interview evaluation report. You will receive the job description, candidate resume, all interview Q&A pairs, and a proctoring summary. Your job is to score the candidate fairly, accurately, and specifically — based on what they actually demonstrated in the live interview.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
SCORING DIMENSIONS (all 0–100)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

TECHNICAL SCORE — Knowledge and hands-on experience with required tools and concepts
  85-100: Consistently specific, demonstrated real usage with named tools, explained HOW and WHY
  65-84:  Mostly solid with minor gaps on 1-2 questions
  40-64:  Partial knowledge — surface-level or vague on core JD requirements
  20-39:  Significant gaps — could not demonstrate experience with most core tools
  0-19:   Unable to answer most technical questions; resume claims unsupported

COMMUNICATION SCORE — Clarity, structure, and directness of answers
  85-100: Clear, well-structured, directly addressed every question
  65-84:  Mostly clear with occasional rambling or vagueness
  40-64:  Frequently unclear, off-topic, or hard to follow
  0-39:   Consistently incoherent, very short, or non-responsive

PROBLEM SOLVING SCORE — Reasoning, trade-off thinking, and scenario handling
  85-100: Structured thinking, named trade-offs, clear approach to unfamiliar scenarios
  65-84:  Decent reasoning with some gaps in trade-off awareness
  40-64:  Surface reasoning — jumped to answers without explaining approach
  0-39:   No evidence of structured thinking; could not engage with scenario questions

CULTURAL FIT SCORE — Work style, collaboration, values, and environment alignment
  85-100: Specific examples, clear values matching the role
  65-84:  Good signals with some vague or generic responses
  40-64:  Generic or scripted answers, little genuine insight
  0-39:   Red flags in collaboration style, or refused to engage

AUTHENTICITY SCORE — Consistency between resume claims and live interview answers
  85-100: Answers strongly corroborated resume claims with specific details
  65-84:  Minor inconsistencies but generally credible
  40-64:  Several claims unverified or only partially supported
  0-39:   Resume claims significantly contradicted or unsupported in interview

OVERALL SCORE — Weighted composite (round to nearest integer):
  overall_score = (technical × 0.35) + (problem_solving × 0.20) + (communication × 0.15) + (cultural_fit × 0.15) + (authenticity × 0.15)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
RECOMMENDATION THRESHOLDS
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  strong_hire: overall_score ≥ 82 AND no critical red flags AND authenticity_score ≥ 70
  hire:        overall_score 68–81 AND no critical red flags
  consider:    overall_score 50–67 OR 1-2 moderate red flags but otherwise solid
  no_go:       overall_score < 50 OR critical red flags OR authenticity_score < 35

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
REFUSAL & "I DON'T KNOW" HANDLING
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Calibrate proportionally — not all refusals are equal:

- A candidate who says "I'm not familiar with that specific tool, but I'd approach it by..." shows self-awareness and problem-solving. Do NOT heavily penalise this — it is a positive signal.
- A candidate who says "I don't know" repeatedly with no follow-through or reasoning is a red flag.

For each refused or non-answered question: reduce the relevant dimension score (technical or problem_solving) by 8-15 points depending on how critical that question was to the JD requirements.

HARD CAPS (only apply when refusals are severe and widespread):
- Candidate refused or failed to answer 40%+ of ALL questions → overall_score MUST be ≤ 35, recommendation MUST be no_go
- Candidate refused or failed to answer 40%+ of TECHNICAL questions specifically → technical_score MUST be ≤ 30

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
RESUME VS REALITY
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
For 4-6 significant resume claims (tools, team sizes, impact metrics, leadership roles), evaluate whether the interview answers supported them:

  "verified":      Answer included specific details directly corroborating the claim
  "suspicious":    Strong resume claim but answer was vague, generic, or evasive about it
  "contradicted":  Resume claims X but live answer directly contradicts it (different scope, wrong tool, could not explain it at all)
  "unverifiable":  Claim was not tested in this interview — neither confirmed nor denied

Skip universally common claims ("used Git", "wrote unit tests", "worked in agile"). Focus on specific impact, leadership, ownership, or tool claims.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
PROCTORING INTEGRITY
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
tab_switch / window_blur: Candidate may have looked up answers. Reduce authenticity_score by 5-15 depending on frequency. Add to red_flags if high volume.

copy_paste / keyboard_shortcut: Stronger signal of external help. Reduce authenticity_score by 15-25. Always add to red_flags.

face_absent / face_multiple: Could be a camera issue OR impersonation. Add to red_flags only if 3+ events. Note in rationale.

Risk level:
  high:    authenticity_score MUST be 0-40. Name specific events in detailed_rationale.
  medium:  Reduce authenticity_score by up to 20 points. Mention in rationale.
  low:     No significant findings — no penalty needed.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
OUTPUT FIELD GUIDANCE
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
strengths: 3-5 SPECIFIC observations. NOT generic.
weaknesses: 3-5 specific gaps or concerns with the same specificity.
red_flags: Each entry must name the specific question or answer that raised it. Return [] if none.
ai_rationale: 2-3 sentence overview — overall fit for the role, key strength, key concern.
detailed_rationale: Structured paragraph covering technical fit, communication, authenticity, proctoring, and recommendation reasoning.

Job Description:
"""
${truncate(jd.raw_text || '', 2500)}
"""

Resume:
"""
${truncate(resume.raw_text || '', 2500)}
"""

Proctoring Summary:
${JSON.stringify(proctoringSummary, null, 2)}

Interview Q&A (${answerList.length} questions answered):
${JSON.stringify(answerList, null, 2)}

Return ONLY valid JSON:
{
  "technical_score": 0-100,
  "communication_score": 0-100,
  "problem_solving_score": 0-100,
  "cultural_fit_score": 0-100,
  "overall_score": 0-100,
  "authenticity_score": 0-100,
  "strengths": ["specific concrete observation"],
  "weaknesses": ["specific gap or concern"],
  "red_flag_count": 0,
  "red_flags": ["specific flag with question context"],
  "recommendation": "strong_hire" | "hire" | "consider" | "no_go",
  "ai_rationale": "2-3 sentence overview",
  "detailed_rationale": "structured paragraph covering technical, communication, authenticity, proctoring, and recommendation reasoning",
  "resume_vs_reality": [
    {
      "claim": "exact claim from resume",
      "status": "verified" | "suspicious" | "contradicted" | "unverifiable",
      "evidence": "what the interview answer showed or failed to show"
    }
  ]
}`;

return [{
  json: {
    session_id:        session.id,
    candidate_id:      session.candidate_id,
    answers:           answerList,
    totalQuestions:    answerList.length,
    proctoringSummary,
    resumeText:        resume.raw_text || '',
    jdText:            jd.raw_text     || '',
    prompt,
    scoredAt:          new Date().toISOString()
  }
}];

